  const point = mean(differences);
  let state = seed >>> 0;
  const random = () => {
    state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
    return state / 0x100000000;
  };
  const bootstrapMeans = [];
  for (let sample = 0; sample < bootstrapSamples; sample += 1) {
    let total = 0;
    for (let index = 0; index < differences.length; index += 1) {
      total += differences[Math.floor(random() * differences.length)];
    }
    bootstrapMeans.push(total / differences.length);
  }
  const alpha = (1 - confidence) / 2;
  return {
    estimate: round(point),
    confidenceLevel: confidence,
    lower: round(quantile(bootstrapMeans, alpha)),
    upper: round(quantile(bootstrapMeans, 1 - alpha)),
    direction: point > 0 ? 'positive' : point < 0 ? 'negative' : 'zero',
    zeroOrNegative: point <= 0
  };
}

/**
 * E01-compatible pass^k: among k paired repetitions, a case passes when all
 * k repetitions succeed. `passAtK` is reported for k=1..repetitions; the
 * primary experiment uses the pre-registered `passK` value.
 */
export function passKByCase(results, repetitions, passK) {
  assertEqual(Number.isInteger(passK) && passK >= 1 && passK <= repetitions, 'passK is outside the repetition range');
  const grouped = new Map();
  for (const result of results) {
    if (!grouped.has(result.caseId)) grouped.set(result.caseId, []);
    grouped.get(result.caseId).push(result);
  }
  const values = [];
  for (const caseResults of grouped.values()) {
    const selected = caseResults.slice(0, passK);
    values.push(selected.length === passK && selected.every((result) => result.success) ? 1 : 0);
  }
  return mean(values);
}

function normalizeResult(result, fixtureCase, condition, repetition) {
  assertEqual(result && typeof result === 'object', `missing result for ${fixtureCase.id}/${condition}/${repetition}`);
  assertEqual(typeof result.success === 'boolean', `success must be boolean for ${fixtureCase.id}/${condition}/${repetition}`);
  assertEqual(typeof result.blocked === 'boolean', `blocked must be boolean for ${fixtureCase.id}/${condition}/${repetition}`);
  assertEqual(typeof result.safetyViolation === 'boolean', `safetyViolation must be boolean for ${fixtureCase.id}/${condition}/${repetition}`);
  const retainedIds = [...(result.retainedIds ?? [])].sort();
  const evictedIds = [...(result.evictedIds ?? [])].sort();
  return {
    caseId: fixtureCase.id,
    condition,
    repetition,
    success: result.success,
    blocked: result.blocked,
    safetyViolation: result.safetyViolation,
    latencyMs: finiteNumber(result.latencyMs),
    inputTokens: finiteNumber(result.inputTokens),
    outputTokens: finiteNumber(result.outputTokens),
    totalTokens: finiteNumber(result.inputTokens) + finiteNumber(result.outputTokens),
    retainedIds,
    evictedIds
  };
}

function aggregateCondition(rows) {
  const latencies = rows.map((row) => row.latencyMs);
  const tokens = rows.map((row) => row.totalTokens);
  return {
    observations: rows.length,
    successRate: round(mean(rows.map((row) => (row.success ? 1 : 0)))),
    blockedRate: round(mean(rows.map((row) => (row.blocked ? 1 : 0)))),
    safetyViolationRate: round(mean(rows.map((row) => (row.safetyViolation ? 1 : 0)))),
    latencyMs: { p50: round(quantile(latencies, 0.5)), p95: round(quantile(latencies, 0.95)) },
    tokensProxy: {
      total: round(tokens.reduce((sum, value) => sum + value, 0)),
      perObservation: round(mean(tokens)),
      p50: round(quantile(tokens, 0.5)),
      p95: round(quantile(tokens, 0.95))
    }
  };
}

function pairRows(baselineRows, treatmentRows) {
  const baseline = new Map(baselineRows.map((row) => [`${row.caseId}:${row.repetition}`, row]));
  const treatment = new Map(treatmentRows.map((row) => [`${row.caseId}:${row.repetition}`, row]));
  const keys = [...baseline.keys()].filter((key) => treatment.has(key)).sort();
  assertEqual(keys.length === baseline.size && keys.length === treatment.size, 'baseline and treatment observations are not paired');
  return keys.map((key) => [baseline.get(key), treatment.get(key)]);
}

function metricValue(row, metric) {
  switch (metric) {
    case 'success': return row.success ? 1 : 0;
    case 'blocked': return row.blocked ? 1 : 0;
    case 'safetyViolation': return row.safetyViolation ? 1 : 0;
    case 'latencyMs': return row.latencyMs;
    case 'tokens': return row.totalTokens;
    default: throw new Error(`unsupported metric: ${metric}`);
  }
}

/**
 * Run the complete deterministic experiment. `adapter.runCase` is called with
 * a fresh isolated RuntimeMemoryStore for every invocation. The adapter must
 * not share stores between conditions or repetitions.
 */
export async function runPairedAblation(fixtureInput, adapter, options = {}) {
  const fixture = validateFixture(fixtureInput);
  assertEqual(adapter && typeof adapter.runCase === 'function', 'adapter.runCase is required');
  const bootstrapSamples = options.bootstrapSamples ?? 10000;
  const confidence = options.confidence ?? 0.95;
  const rows = { fifo: [], 'type-aware': [] };\n  for (const condition of CONDITIONS) {
    for (const fixtureCase of fixture.cases) {
      for (let repetition = 0; repetition < fixture.repetitions; repetition += 1) {
        const seed = (fixture.seed + repetition) >>> 0;
        const raw = await adapter.runCase(fixtureCase, { condition, repetition, seed });
        rows[condition].push(normalizeResult(raw, fixtureCase, condition, repetition));
      }
    }
  }

  const pairs = pairRows(rows.fifo, rows['type-aware']);
  const policyDifferences = pairs.filter(([baseline, treatment]) =>
    baseline.retainedIds.join('\u0000') !== treatment.retainedIds.join('\u0000') ||
    baseline.evictedIds.join('\u0000') !== treatment.evictedIds.join('\u0000'));
  assertEqual(policyDifferences.length > 0, 'eviction validation failed: retained/evicted sets are identical in every pair');

  const passAtK = {};
  for (let k = 1; k <= fixture.repetitions; k += 1) {
    passAtK[`passAt${k}`] = round(passKByCase(rows.fifo, fixture.repetitions, k));
    passAtK[`passAt${k}_treatment`] = round(passKByCase(rows['type-aware'], fixture.repetitions, k));
  }

  const primaryMetric = fixture.metrics.primary;
  const effects = {};
  for (const metric of ['success', 'latencyMs', 'tokens', 'blocked', 'safetyViolation']) {
    effects[metric] = pairedEffect(pairs.map(([baseline, treatment]) => [metricValue(baseline, metric), metricValue(treatment, metric)]), {
      confidence,
      bootstrapSamples,
      seed: fixture.seed
    });
  }

  const primaryPairs = pairs.map(([baseline, treatment]) => [metricValue(baseline, primaryMetric), metricValue(treatment, primaryMetric)]);
  const primaryEffect = pairedEffect(primaryPairs, { confidence, bootstrapSamples, seed: fixture.seed });
  const budget = fixture.metrics.degradationBudget;
  const degradation = primaryEffect.estimate;
  const degradationAllowed = degradation <= (budget.maxPrimaryDegradation ?? 0);
  const passK = fixture.metrics.passK ?? 1;
  const baselinePassK = passAtK[`passAt${passK}`];
  const treatmentPassK = passAtK[`passAt${passK}_treatment`];
  const report = {
    schemaVersion: 1,
    experiment: 'E02-phase-4-type-aware-eviction-paired-ablation',
    fixtureSha256: sha256(JSON.stringify(fixture)),
    seed: fixture.seed,
    repetitions: fixture.repetitions,
    cases: fixture.cases.length,
    baseline: 'fifo',
    treatment: 'type-aware',
    preregistration: { primaryMetric, passK, degradationBudget: budget },
    componentValidation: {
      differentPairCount: policyDifferences.length,
      totalPairCount: pairs.length,
      passed: true
    },
    metrics: {
      baseline: aggregateCondition(rows.fifo),
      treatment: aggregateCondition(rows['type-aware']),
      passAtK
    },
    effects,
    primaryEffect,
    decision: {
      noBenefitClaim: primaryEffect.zeroOrNegative,
      withinDegradationBudget: degradationAllowed,
      productDefaultsChanged: false,
      productLocksChanged: false,
      approvalChanged: false
    },
    rows: [...rows.fifo, ...rows['type-aware']]
  };
  return report;
}

export function formatPairedAblationReport(report) {
  const lines = [
    '# E02 paired ablation report',
    '',
    `- Baseline: \`${report.baseline}\`; treatment: \`${report.treatment}\``,
    `- Cases/repetitions: ${report.cases}/${report.repetitions}`,
    `- Component validation: ${report.componentValidation.differentPairCount}/${report.componentValidation.totalPairCount} pairs differ`,
    `- Primary effect (${report.preregistration.primaryMetric}): ${report.primaryEffect.estimate} (95% CI ${report.primaryEffect.lower}..${report.primaryEffect.upper})`,
    `- Zero or negative effect: ${report.decision.noBenefitClaim ? 'yes' : 'no'}`,
    '- Product defaults, product locks, and approval were not changed.'
  ];
  for (const condition of ['baseline', 'treatment']) {
    const metrics = report.metrics[condition];
    lines.push(`- ${condition}: success=${metrics.successRate}, pass@k=${report.metrics.passAtK[`passAt${report.preregistration.passK}_${condition === 'treatment' ? 'treatment' : ''}`]}, p50=${metrics.latencyMs.p50}ms, p95=${metrics.latencyMs.p95}ms, tokens=${metrics.tokensProxy.total}, blocked=${metrics.blockedRate}, safety=${metrics.safetyViolationRate}`);
  }
  return `${lines.join('\n')}\n`;
}
